mapper.select:
with recursive tree (post_id, parent_id) as(
    select t1.post_id, t1.parent_id from sys_post_diagram t1 where post_id = #{postId}
    union
    select t2.post_id, t2.parent_id from sys_post_diagram t2 join tree on t2.parent_id = tree.post_id
)
select distinct tree.post_id from tree JOIN sys_post u on tree.post_id = u.post_id
